cat > src/document/storage.test.ts <<'EOF'
import { describe, expect, it } from 'vitest'
import {
  DOCUMENT_STORAGE_KEY,
  loadDocument,
  type StorageLike,
  saveDocument,
} from './storage'

const createFakeStorage = (
  initial: Record<string, string> = {},
): StorageLike & { readonly entries: () => Record<string, string> } => {
  const data = new Map(Object.entries(initial))
  return {
    getItem: (key) => data.get(key) ?? null,
    setItem: (key, value) => {
      data.set(key, value)
    },
    entries: () => Object.fromEntries(data),
  }
}

const throwingStorage: StorageLike = {
  getItem: () => {
    throw new Error('storage unavailable')
  },
  setItem: () => {
    throw new Error('quota exceeded')
  },
}

describe('loadDocument', () => {
  it('returns the fallback when nothing is stored', () => {
    expect(loadDocument(createFakeStorage(), 'sample')).toBe('sample')
  })

  it('returns the stored text', () => {
    const storage = createFakeStorage({ [DOCUMENT_STORAGE_KEY]: '# Saved' })
    expect(loadDocument(storage, 'sample')).toBe('# Saved')
  })

  it('keeps an empty stored document instead of restoring the fallback', () => {
    const storage = createFakeStorage({ [DOCUMENT_STORAGE_KEY]: '' })
    expect(loadDocument(storage, 'sample')).toBe('')
  })

  it('returns the fallback when storage throws', () => {
    expect(loadDocument(throwingStorage, 'sample')).toBe('sample')
  })

  it('returns the fallback when storage is unavailable', () => {
    expect(loadDocument(null, 'sample')).toBe('sample')
  })
})

describe('saveDocument', () => {
  it('stores only the document string under a single key', () => {
    const storage = createFakeStorage()
    expect(saveDocument(storage, '# Hello')).toBe(true)
    expect(storage.entries()).toEqual({ [DOCUMENT_STORAGE_KEY]: '# Hello' })
  })

  it('round-trips through loadDocument', () => {
    const storage = createFakeStorage()
    saveDocument(storage, 'first')
    saveDocument(storage, 'second')
    expect(loadDocument(storage, 'sample')).toBe('second')
  })

  it('reports failure without throwing when storage throws', () => {
    expect(saveDocument(throwingStorage, 'text')).toBe(false)
  })

  it('reports failure when storage is unavailable', () => {
    expect(saveDocument(null, 'text')).toBe(false)
  })
})
EOF
cat > src/document/autosave.test.ts <<'EOF'
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import { createAutosave } from './autosave'

describe('createAutosave', () => {
  beforeEach(() => {
    vi.useFakeTimers()
  })

  afterEach(() => {
    vi.useRealTimers()
  })

  it('saves only the latest text after the delay', () => {
    const save = vi.fn()
    const autosave = createAutosave({ save, delayMs: 300 })

    autosave.schedule('a')
    vi.advanceTimersByTime(200)
    autosave.schedule('ab')
    vi.advanceTimersByTime(299)
    expect(save).not.toHaveBeenCalled()

    vi.advanceTimersByTime(1)
    expect(save).toHaveBeenCalledTimes(1)
    expect(save).toHaveBeenCalledWith('ab')
  })

  it('flush saves the pending text immediately and only once', () => {
    const save = vi.fn()
    const autosave = createAutosave({ save, delayMs: 300 })

    autosave.schedule('pending')
    autosave.flush()
    vi.advanceTimersByTime(1000)

    expect(save).toHaveBeenCalledTimes(1)
    expect(save).toHaveBeenCalledWith('pending')
  })

  it('flush does nothing when nothing is pending', () => {
    const save = vi.fn()
    const autosave = createAutosave({ save, delayMs: 300 })

    autosave.flush()

    expect(save).not.toHaveBeenCalled()
  })

  it('cancel drops the pending text', () => {
    const save = vi.fn()
    const autosave = createAutosave({ save, delayMs: 300 })

    autosave.schedule('dropped')
    autosave.cancel()
    vi.advanceTimersByTime(1000)

    expect(save).not.toHaveBeenCalled()
  })
})
EOF
cat > config/openrouter-proxy.test.ts <<'EOF'
import type { ProxyOptions } from 'vite'
import { describe, expect, it } from 'vitest'
import {
  OPENROUTER_PROXY_PREFIX,
  OPENROUTER_TARGET,
  buildOpenRouterProxy,
  buildOpenRouterProxyTable,
  rewriteOpenRouterPath,
  setAuthorization,
} from './openrouter-proxy'

type ProxyServerArg = Parameters<NonNullable<ProxyOptions['configure']>>[0]
type ProxyReqHandler = (proxyReq: FakeProxyReq) => void

type FakeProxyReq = {
  readonly setHeader: (name: string, value: string) => void
  readonly headers: () => Record<string, string>
}

const createFakeProxyReq = (initial: Record<string, string>): FakeProxyReq => {
  const headers = new Map(
    Object.entries(initial).map(([name, value]) => [name.toLowerCase(), value]),
  )
  return {
    setHeader: (name, value) => {
      headers.set(name.toLowerCase(), value)
    },
    headers: () => Object.fromEntries(headers),
  }
}

const captureProxyReqHandler = (options: ProxyOptions): ProxyReqHandler => {
  const handlers: ProxyReqHandler[] = []
  const fakeProxy = {
    on: (event: string, handler: ProxyReqHandler) => {
      if (event === 'proxyReq') handlers.push(handler)
    },
  }
  options.configure?.(fakeProxy as unknown as ProxyServerArg, options)
  const [handler] = handlers
  if (!handler) throw new Error('proxyReq handler was not registered')
  return handler
}

describe('rewriteOpenRouterPath', () => {
  it('strips the proxy prefix', () => {
    expect(rewriteOpenRouterPath('/api/openrouter/models')).toBe('/models')
  })

  it('keeps nested paths and query strings', () => {
    expect(
      rewriteOpenRouterPath('/api/openrouter/generation?id=gen-1'),
    ).toBe('/generation?id=gen-1')
  })
})

describe('setAuthorization', () => {
  it('overwrites whatever Authorization the browser sent', () => {
    const proxyReq = createFakeProxyReq({ Authorization: 'Bearer placeholder' })
    setAuthorization('real-key')(proxyReq)
    expect(proxyReq.headers().authorization).toBe('Bearer real-key')
  })

  it('adds Authorization when the browser sent none', () => {
    const proxyReq = createFakeProxyReq({})
    setAuthorization('real-key')(proxyReq)
    expect(proxyReq.headers().authorization).toBe('Bearer real-key')
  })
