export type Autosave = {
  readonly schedule: (text: string) => void
  readonly flush: () => void
  readonly cancel: () => void
}

type Pending = { readonly text: string; readonly timer: number }

export const createAutosave = ({ save, delayMs }: AutosaveOptions): Autosave => {
  let pending: Pending | null = null

  const cancel = () => {
    if (pending) clearTimeout(pending.timer)
    pending = null
  }

  const flush = () => {
